SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "朱温入郓州，以庞师古为天平留后。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p004·原文件第9行", "note": "原文：硃全忠入郓州，以庞师古为天平留后。；核对说明：旧五代史初署朱友裕与主书先庞师古、三月再表友裕不同，独立附异记。", "status": "draft", "id": "89715529-b9e8-54c6-8392-d48e7c839930", "subject_id": "2b7eb865-bb07-56f6-90a6-15416392395d", "source_id": "976ed666-858f-5448-a34b-ed1d8113814f"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "897年正月郓州陷后；确日未载", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p004·原文件第9行", "note": "原文：硃全忠入郓州，以庞师古为天平留后。；核对说明：旧五代史初署朱友裕与主书先庞师古、三月再表友裕不同，独立附异记。", "status": "draft", "id": "ed62b6b4-1c36-5b6a-b2a2-da774107a225", "subject_id": "2b7eb865-bb07-56f6-90a6-15416392395d", "source_id": "976ed666-858f-5448-a34b-ed1d8113814f"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱温：入城署任者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p004·原文件第9行", "note": "原文：硃全忠入郓州，以庞师古为天平留后。硃瑾留大将康怀贞守兗州。与河东将史俨、李承嗣掠徐州之境给军食。全忠闻之，遣嵩从周将兵袭兗州。怀贞闻郓州已失守，汴兵奄至，遂降。二月，戊申，从周入兗州，获瑾妻子。硃瑾还，无所归，帅其众趋沂州，刺史尹处宾不纳，走保海州，为汴兵所逼，与史俨、李承嗣拥州民度淮，奔杨行密。行密逆之于高邮，表瑾领武宁节度使。全忠纳瑾之妻，引兵还，张夫人逆于封丘，全忠以得瑾妻告之。夫人请见之，瑾妻拜，夫人答拜，且泣曰：“兗、郓与司空同姓，约为兄弟，以小故恨望，起兵相攻，使吾姒辱于此。他日汴州失守，吾亦如吾姒之今日乎！”全忠乃送瑾妻于佛寺为尼，斩硃宣于汴桥。于是郓、齐、曹、棣、兗、沂、密、徐、宿、陈、许、郑、滑、濮皆入于全忠。惟王师范保淄青一道，亦服于全忠。李存信在魏州，闻兗、郓皆陷，引兵还。淮南旧善水战，不知骑射，及得河东、兗、郓兵，军声大振。史俨、李承嗣皆河东骁将，李克用深惜之，遣使间道诣杨行密请之。行密许之，亦遣使诣克用修好。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "d19852d4-86cc-51eb-babf-c7c6a4109ad2", "subject_id": "0555e455-34d4-54ef-b93e-b0e6425018ab", "source_id": "976ed666-858f-5448-a34b-ed1d8113814f"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱温：入城署任者。", "citation": "卷261·乾宁四年（897）·zztj-v261-y0897-p004·原文件第9行", "note": "原文：硃全忠入郓州，以庞师古为天平留后。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "598d27ed-a549-52af-81fc-8550609fc4b4", "su